  getHomeDashboard: {
    parameters: {
      query?: never;
      header?: never;
      path?: never;
      cookie?: never;
    };
    requestBody?: never;
    responses: {
      /** @description The home dashboard */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': {
            activation: {
              steps: {
                /** @enum {string} */
                key:
                  | 'install_widget'
                  | 'invite_teammate'
                  | 'customize_widget'
                  | 'add_canned_response'
                  | 'set_up_ai_agent';
                done: boolean;
              }[];
              /** @description How many steps are done. */
              completed: number;
              /** @description How many steps there are. */
              total: number;
            };
            live: {
              /** @description Distinct people on the site now (open chat or recent visit). */
              visitors_online: number;
              /** @description Conversations open right now. */
              ongoing_chats: number;
              /** @description Teammates set to accept chats (not suspended). */
              agents_online: number;
            };
            weekly: {
              range: {
                /** Format: date-time */
                from: string;
                /** Format: date-time */
                to: string;
              };
              /** @description Conversations started in the window. */
              chats: number;
              /** @description Conversations started in the window that are now resolved. */
              resolved: number;
              satisfaction: {
                good: number;
                bad: number;
                responses: number;
                /** @description Good ÷ rated, or null when nobody rated. */
                score: number | null;
              };
              previous: {
                range: {
                  /** Format: date-time */
                  from: string;
                  /** Format: date-time */
                  to: string;
                };
                chats: number;
                resolved: number;
                satisfaction_score: number | null;
              };
            };
          };
        };
      };
      401: components['responses']['Unauthorized'];
      403: components['responses']['Forbidden'];
      429: components['responses']['TooManyRequests'];
    };
  };
